/* ========================================================================
   CLIVEMAN 3.1  -  engine/easter-egg-audio.js
   The secret crew-credits Easter egg audio, embedded as a base64 data URI
   so the game ships as a self-contained set of files with no loose .mp3 /
   assets directory. On load this wires the data into the #easterEggAudio
   element that playFinaleEasterEgg() (story/finale.js) plays.

   Source: 64 kbps MPEG layer III, 44.1 kHz stereo.
   ======================================================================== */
(function(){
  var EASTER_EGG_AUDIO_B64 = "";
  function wire(){
    var el = document.getElementById('easterEggAudio');
    if(el){ el.src = 'data:audio/mpeg;base64,' + EASTER_EGG_AUDIO_B64; }
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', wire);
  } else {
    wire();
  }
})();
